import time

def charge_with_retry(client, invoice, attempts=4):
    delay = 2
    for i in range(attempts):
        try:
            return client.charge(invoice)
        except TransientError:
            time.sleep(delay)
            delay *= 2
    raise ChargeFailed(invoice.id)
